import{_ as I,o as g,c as a,ag as e}from"./chunks/framework.WmBmIPw-.js";const l="data:image/svg+xml;base64,",m=JSON.parse('{"title":"第 1 课 · 基本概念","description":"","frontmatter":{},"headers":[],"relativePath":"reinforcement-learning/basic-concepts.md","filePath":"reinforcement-learning/basic-concepts.md","lastUpdated":1794321750000}'),r={name:"reinforcement-learning/basic-concepts.md"};function s(t,i,o,n,p,C){return g(),a("div",null,[...i[0]||(i[0]=[e('<h1 id="第-1-课-·-基本概念" tabindex="-1">第 1 课 · 基本概念 <a class="header-anchor" href="#第-1-课-·-基本概念" aria-label="Permalink to &quot;第 1 课 · 基本概念&quot;">​</a></h1><p>强化学习要回答两个相连的问题：智能体怎样在环境里做决策，以及怎样判断这些决策带来的结果。赵世钰老师在这一课用同一个 3×3 网格世界串起两者。前半讲状态、动作和策略，后半用奖励与回报评价路线，再把这些概念归入马尔可夫决策过程。</p><p>课程来源：<a href="https://www.bilibili.com/video/BV1sd4y167NS?p=2" target="_blank" rel="noreferrer">B 站第 2 个分 P（状态、动作与策略）</a> · <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=3" target="_blank" rel="noreferrer">B 站第 3 个分 P（奖励、回报与 MDP）</a></p><h2 id="_1-从网格世界看一次决策" tabindex="-1">1. 从网格世界看一次决策 <a class="header-anchor" href="#_1-从网格世界看一次决策" aria-label="Permalink to &quot;1. 从网格世界看一次决策&quot;">​</a></h2><p>机器人的任务是从给定起点走到右下角的目标格 s₉，并尽量避免撞墙、绕路或经过黄色禁区 s₆、s₇。九个格子按行编号为 s₁ 到 s₉。</p><ul><li><strong>状态</strong>：描述智能体此刻的处境。在网格里，一个格子就能表示状态，也可以用坐标 (x, y)。所有可能的状态构成状态空间。现实机器人还可能需要用速度等信息描述状态。</li><li><strong>动作</strong>：智能体可以发出的指令。本例中 a₁ 到 a₅ 依次是上、右、下、左和原地不动。动作集合可以随状态变化。</li><li><strong>状态转移</strong>：环境收到指令后给出的下一状态。例如在 s₁ 向右会到 s₂，向上撞墙则仍留在 s₁。课上的禁区允许进入但会扣分，所以从 s₅ 向右会到 s₆；如果把禁区建模为墙，才会留在 s₅。</li></ul><p>在确定性环境中，给定状态与动作就能查出唯一的下一状态。若存在风扰动，同一个指令可能有多个结果，就用转移概率 p(s′ | s, a) 来表示。比如在 s₁ 发出向右指令后，可能各有 0.5 的概率落在 s₂ 或 s₅。 <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=2&amp;t=169" target="_blank" rel="noreferrer">回看第 2 个分 P · 02:49</a></p><h2 id="_2-策略负责选动作-环境负责给结果" tabindex="-1">2. 策略负责选动作，环境负责给结果 <a class="header-anchor" href="#_2-策略负责选动作-环境负责给结果" aria-label="Permalink to &quot;2. 策略负责选动作，环境负责给结果&quot;">​</a></h2><p>策略 π(a | s) 规定在状态 s 下选动作 a 的概率。同一个状态下，所有动作的概率之和为 1。</p><ul><li><strong>确定性策略</strong>：在 s₁ 总是向右，向右的概率为 1。</li><li><strong>随机策略</strong>：在 s₁ 向右和向下各有 0.5 的概率。实现时可以在 [0, 1) 均匀抽样，前半段向右，后半段向下。</li></ul><p>随机性可以来自两处。π(a | s) 回答「智能体发出哪个指令」，p(s′ | s, a) 回答「这个指令发出后落在哪一格」。即使策略总是选向右，环境也可能因风扰动而给出不同落点。反过来，即使环境完全确定，随机策略也可能走出不同路径。 <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=2&amp;t=770" target="_blank" rel="noreferrer">回看第 2 个分 P · 12:50</a></p><h2 id="_3-奖励评价一步-回报评价一条轨迹" tabindex="-1">3. 奖励评价一步，回报评价一条轨迹 <a class="header-anchor" href="#_3-奖励评价一步-回报评价一条轨迹" aria-label="Permalink to &quot;3. 奖励评价一步，回报评价一条轨迹&quot;">​</a></h2><p>奖励是执行动作后收到的一个数。课程为网格设定了四条规则：试图越界得 −1，进入禁区得 −1，到达目标得 +1，其余情况得 0。奖励把「希望智能体怎么做」变成可计算的反馈。比如在 s₁，向上撞墙和主动停留都会留在原地，但奖励分别是 −1 和 0。如果同一状态和动作的奖励大小也可能变化，就用 p(r | s, a) 表示得到各个奖励值的概率。 <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=3&amp;t=4" target="_blank" rel="noreferrer">回看第 3 个分 P · 00:04</a></p><p>轨迹把多步交互连起来：从当前状态出发，选动作，收到奖励并转入下一状态，再继续决策。对一条有限轨迹，可以把每步奖励加起来，得到它的未折扣回报。</p><figure><img src="'+l+'" alt="两条从 s₁ 到 s₉ 的网格路线。路线 A 经 s₂、s₅、s₈ 避开禁区，路线 B 经 s₄、s₇、s₈ 穿过一个禁区。" width="620" height="280"><figcaption>根据课程的网格世界例子重绘。</figcaption></figure><ul><li><strong>路线 A</strong>：s₁ → s₂ → s₅ → s₈ → s₉。避开禁区，回报为 0 + 0 + 0 + 1 = 1。</li><li><strong>路线 B</strong>：s₁ → s₄ → s₇ → s₈ → s₉。进入一次禁区，回报为 0 − 1 + 0 + 1 = 0。</li></ul><p>两条路线都在四步内到达目标，奖励让它们的差别可以直接比较。如果同一策略能产生多条轨迹，单次回报只是一次结果，评价策略还需要考虑这些结果各自发生的概率。 <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=3&amp;t=329" target="_blank" rel="noreferrer">回看第 3 个分 P · 05:29</a></p><h2 id="_4-任务何时结束-决定回报怎么算" tabindex="-1">4. 任务何时结束，决定回报怎么算 <a class="header-anchor" href="#_4-任务何时结束-决定回报怎么算" aria-label="Permalink to &quot;4. 任务何时结束，决定回报怎么算&quot;">​</a></h2><p><strong>回合（episode）</strong> 是从起点到终止状态的一次交互。若到达 s₉ 就停止，上一节的两条轨迹各构成一个回合。持续型任务没有这类终止点，交互会一直进行。</p><p>把到达目标后的行为也纳入模型时，课上比较了两种设定：</p><ul><li><strong>吸收状态</strong>：到达目标后永远留在那里，后续奖励都是 0。这保留了「到达即结束」的回报。</li><li><strong>普通状态</strong>：到达目标后继续按策略行动，仍可离开或停留。课上采用这个设定，并用留在 s₉、每步继续得到 +1 的策略说明无限累加的问题。</li></ul><p>如果奖励序列为 0, 0, 0, 1, 1, …，直接求和会发散。引入折扣因子 γ 后，从当前时刻起，第一个奖励权重为 1，第二个为 γ，第三个为 γ²，依次类推：</p><blockquote><p>Gₜ = Rₜ₊₁ + γRₜ₊₂ + γ²Rₜ₊₃ + …，其中 0 ≤ γ &lt; 1。</p></blockquote><p>这个例子的折扣回报是 γ³ + γ⁴ + … = γ³ / (1 − γ)。在奖励有界时，这样的无限和是有限的。γ 越小，越看重眼前的奖励；γ 越接近 1，远期奖励相对越有分量。 <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=3&amp;t=515" target="_blank" rel="noreferrer">回看第 3 个分 P · 折扣回报 08:35</a> · <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=3&amp;t=712" target="_blank" rel="noreferrer">回合与持续型任务 11:52</a></p><h2 id="_5-用马尔可夫决策过程统一描述" tabindex="-1">5. 用马尔可夫决策过程统一描述 <a class="header-anchor" href="#_5-用马尔可夫决策过程统一描述" aria-label="Permalink to &quot;5. 用马尔可夫决策过程统一描述&quot;">​</a></h2><p>一个马尔可夫决策过程（MDP）给出状态集合、每个状态的可选动作，以及每个状态与动作可能得到的奖励。给定当前状态和动作，课程分别用 p(s′ | s, a) 和 p(r | s, a) 描述下一状态与奖励的概率。</p><p><strong>马尔可夫性质</strong>：一旦知道当前状态和选定动作，预测下一状态和即时奖励就不再需要更早的交互历史。网格世界里，机器人是怎么走到 s₅ 的，不影响它从 s₅ 向右时的结果。若过去的信息确实会改变结果，就需要把相关信息纳入状态。</p><p>策略 π 是在这个模型上选动作的规则。固定策略之后，每个状态的动作概率也确定了，可以把动作平均掉，得到一个只描述状态之间转移的马尔可夫过程。例如，在确定性网格里，若策略规定从 s₁ 各以 0.5 的概率向右和向下，那么下一状态 s₂ 和 s₄ 的概率就是各 0.5。 <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=3&amp;t=921" target="_blank" rel="noreferrer">回看第 3 个分 P · 15:21</a></p>',28)])])}const c=I(r,[["render",s]]);export{m as __pageData,c as default};
